def _mlsb_load_glue(subset):
    """Read a GLUE subset's TRAIN split from the baked DatasetDict.

    MLS-Bench: compute nodes have no network, and `load_dataset("glue", ...)`
    contacts the Hub to resolve the dataset repo even when the arrow cache is
    warm. The data step saves each subset's train split with `save_to_disk`;
    this reads it back. The validation split is the SCORED set of this task and
    is not in the image at all: the fixed evaluator receives its inputs from the
    verifier at evaluation time. The authors' loader wants a `validation` key
    (the training script's in-run eval), so a slice of train stands in for it
    here; the training script then uses a slice of train anyway.
    """
    import os

    from datasets import Dataset, DatasetDict, load_from_disk

    # The baked copy is read-only shared data, and `.map()` writes its cache
    # next to the source arrow file. Materialise an in-memory copy instead: the
    # cache then lands in HF_DATASETS_CACHE (per-run and writable), nothing is
    # written back into the baked data, and concurrent settings in one container
    # cannot race over a cache file.
    root = os.environ.get("MLSB_GLUE_DIR", "/data/lora-one/glue")
    on_disk = load_from_disk(os.path.join(root, subset))
    splits = {k: Dataset.from_dict(v.to_dict()) for k, v in on_disk.items()}
    if "validation" not in splits:
        splits["validation"] = splits["train"].select(range(min(64, len(splits["train"]))))
    return DatasetDict(splits)


def _mlsb_load_saved(name):
    """Read a baked, already-preprocessed (x, y) training set from disk."""
    import os

    from datasets import Dataset, load_from_disk

    root = os.environ.get("MLSB_METAMATH_DIR", "/data/lora-one/meta_math_100k")
    if name != "meta_math_100k":
        raise KeyError(name)
    on_disk = load_from_disk(root)
    return Dataset.from_dict(on_disk.to_dict())

def cache_to_disk(root_datadir):
    """MLS-Bench: disabled.

    The original decorator pickles each loader's result into
    `<pkg>/data_cache/<func>.pkl` and unpickles it on the next call. The
    evaluation process calls the same loaders, so that file is (a) arbitrary
    code executed inside the evaluator and (b) a place to plant forged labels or
    a one-row validation set. The loaders read a baked DatasetDict and take
    under a second, so the cache buys nothing.
    """
    def decorator_cache(func):
        return func

    return decorator_cache
