"""Verifier-only evaluation items and metric for theory-lora-gradient-init.

Host-side in dev (this directory is never bind-mounted); inside the Harbor
bundle it lives only under ``tests/meta/``, which the agent phase cannot read.

Two roles:

* ``inputs_payload(setting)`` -- the withheld INPUTS of one evaluation setting
  (prompts, and for the classification settings the two label words), as the
  JSON the fixed evaluator consumes.  ``edits/mid_edit.py`` emits it as an
  ephemeral create-op right before an evaluation runs; the run script reads it
  into memory and removes it before any editable code starts, and the labels
  are never in it.
* ``score(setting, preds)`` -- the metric, computed by ``parser.py`` where the
  verifier runs, from the per-item predictions the fixed evaluator printed:
  - cola / mrpc: the reference implementation's label-restricted ("soft")
    accuracy (LoRA-One/utils.py::compute_metrics), i.e. the fraction of
    validation items whose own label word out-scores the other one at the
    first decoded position; the evaluator prints the argmax per item, this
    module compares it with the label.
  - gsm8k: the reference `eval_gsm8k.py` metric -- the integer after `####`
    in the greedy completion equals the integer after `####` in the reference
    answer (their `extract_num`, unparsable -> 0 on both sides).

The item files are built by gen_holdout.py from pinned dataset revisions.
"""

import json
import re
from pathlib import Path

_HERE = Path(__file__).resolve().parent
SETTINGS = ("cola", "mrpc", "gsm8k")
_CACHE = {}


def _load(setting):
    if setting not in SETTINGS:
        raise KeyError(f"unknown setting {setting!r}")
    if setting not in _CACHE:
        with open(_HERE / "data" / f"{setting}.json") as fh:
            _CACHE[setting] = json.load(fh)
    return _CACHE[setting]


def kind(setting):
    return _load(setting)["kind"]


def n_items(setting):
    return len(_load(setting)["prompts"])


def inputs_payload(setting):
    """JSON text of the withheld inputs: prompts (+ label words), no labels."""
    d = _load(setting)
    payload = {"setting": setting, "kind": d["kind"], "prompts": list(d["prompts"])}
    if d["kind"] == "cls":
        payload["label_words"] = list(d["label_words"])
    return json.dumps(payload, ensure_ascii=False)


def truth(setting):
    return list(_load(setting)["labels"])


def extract_num(text):
    """Verbatim port of LoRA-One/eval_gsm8k.py::extract_num."""
    match = re.search(r"####\s*(\d+)", text)
    result = match.group(1) if match else ""
    try:
        return int(result.replace(",", ""))
    except Exception:
        return 0


def parse_preds(setting, text):
    """Decode the evaluator's prediction string into a list of ints.

    cls: one character per item, '0' / '1' (index into label_words).
    gen: comma-separated integers, one per item (the evaluator already applied
         extract_num to each completion; an empty field means no number)."""
    k = kind(setting)
    text = text.strip()
    if k == "cls":
        if not re.fullmatch(r"[01]+", text):
            raise ValueError("classification predictions must be a 0/1 string")
        return [int(c) for c in text]
    parts = text.split(",") if text else []
    out = []
    for p in parts:
        p = p.strip()
        out.append(int(p) if re.fullmatch(r"-?\d+", p) else 0)
    return out


def score(setting, preds):
    """Accuracy in [0, 1] of `preds` against the held-out labels; strict length."""
    labels = truth(setting)
    if len(preds) != len(labels):
        raise ValueError(f"{setting}: {len(preds)} predictions for {len(labels)} items")
    if not labels:
        raise ValueError("empty item set")
    correct = sum(int(p == t) for p, t in zip(preds, labels))
    return correct / len(labels)
